import React, { useEffect, useState } from "react";
import Logo from "../../assets/sidebar/logo.png";
import { useNavigate } from "react-router-dom";
import { ReactComponent as Email } from "../../assets/login/email.svg";
import { paths } from "../../utils/path";

export default function ResetPassword() {
  const navigate = useNavigate();
  const [timer, setTimer] = useState(30);

  useEffect(() => {
    const interval = setInterval(() => {
      if (timer > 0) {
        setTimer((prev) => prev - 1);
      } else {
        clearInterval(interval);
      }
    }, 1000);

    return () => clearInterval(interval);
  }, [timer]);

  const sendEmailAgainHandler = () => {
    setTimer(30);
  };

  return (
    <div className="reset_password">
      <img src={Logo} alt="bignlean" />
      <div className="reset_password__content">
        <h3>Reset Password</h3>
        <p className="reset_password__content__text">
          Enter the email associated with your account and we'll send an email
          with instructions to reset your password.
        </p>
        <div className="transparent__input reset_password__input">
          <input
            type="text"
            className="input_transparent"
            placeholder="Enter Email"
          />
          <Email className="transparent__input__icon" />
        </div>

        <button
          className="button-red"
          onClick={() => navigate(`/${paths?.front?.user?.check_mail}`)}
        >
          Send Instructions
        </button>
        <p className="reset_password__content__time">
          Re-send Instructions in{" "}
          {timer !== 0 ? (
            <span>0:{timer}</span>
          ) : (
            <span style={{ cursor: "pointer" }} onClick={sendEmailAgainHandler}>
              Send again
            </span>
          )}
        </p>
      </div>
    </div>
  );
}
